/**
 * Generates the Cursor adapter: a preToolUse command hook that rewrites
 * shell commands into a shaving wrapper, so the terminal output Cursor
 * feeds to the model is already shaved (Cursor ≤ current docs ship no
 * output-replacement contract for native shell tools — see below).
 *
 * Verified against the Cursor hooks documentation (docs/hooks +
 * docs/reference/third-party-hooks, checked 2026-11-02; see VERIFY.md):
 *  - afterShellExecution is observe-only (command/output/duration/sandbox,
 *    no output schema) — it cannot change what the model sees
 *  - postToolUse can replace output only for MCP tools
 *    (updated_mcp_tool_output); for Shell it only offers additional_context,
 *    which ADDS context on top of the untouched raw output
 *  - preToolUse documents updated_input: "Modified tool input to use
 *    instead" — the official, supported way to change a command before it
 *    runs. That is the mechanism this adapter uses.
 *  - the wrapper rewrites the command to:
 *      node "<script>" <base64 of original command> tsh-cursor-wrap
 *    and that wrapper runs the real command (shell:true), captures
 *    stdout/stderr, shaves them with the inlined engine, prints the shaved
 *    form, and exits with the child's exit code.
 *  - hook-mode output is ALWAYS {"permission":"allow"}-shaped JSON with
 *    exit 0: Cursor's permission hooks BLOCK on invalid/missing output, so
 *    a valid allow is the fail-open shape; crashes/timeouts (exit != 2)
 *    fail open by design too.
 *  - conservative wrap whitelist: only commands the engine has a named
 *    rule for (installs / test runners / compilers / bundler builds /
 *    curl-wget) plus `npm|pnpm|yarn|bun test` spellings. Sandboxed
 *    commands, non-Shell tools, and already-wrapped commands are passed
 *    through untouched; interactive/watch commands never match the
 *    whitelist in the first place.
 *  - project hooks run with cwd = project root, so both files are written
 *    by absolute paths at install time (Cursor hooks are project-level;
 *    no marketplace payload exists for this — project hooks.json is the
 *    supported route).
 */
import { loadEngineBundle } from "./claudeBundle.js";
export const CURSOR_HOOK_MARKER = "tokenshave — generated by `npx tokenshave install` (Cursor hook)";
export async function generateCursorHookFiles(generatedAt, version, command, engineBundle) {
    const engine = engineBundle ?? (await loadEngineBundle());
    const hooksJson = `${JSON.stringify({
        version: 1,
        hooks: {
            preToolUse: [
                {
                    matcher: "Shell",
                    command,
                    timeout: 10,
                },
            ],
        },
    }, null, 2)}\n`;
    const wrapJs = `// ${CURSOR_HOOK_MARKER} on ${generatedAt} (tokenshave ${version})
// Uninstall with \`npx tokenshave uninstall\`, or delete this file/directory.
//
// One script, two roles:
//  1. HOOK MODE (Cursor runs it with stdin JSON as a \`preToolUse\` hook):
//     if the Shell command is in the conservative wrap whitelist (installs
//     / test runners / compilers / bundler builds / curl-wget), rewrites it
//     into role 2 via the documented \`updated_input\`. Every output path is
//     a valid {"permission":"allow"} JSON with exit 0 — Cursor permission
//     hooks BLOCK on invalid output, so a valid allow is the fail-open
//     shape. This hook never denies anything.
//  2. WRAPPER MODE (executed as \`node this-file <base64-cmd> tsh-cursor-wrap\`):
//     runs the real command (shell), captures stdout/stderr, shaves both
//     with the inlined engine below (pure computation: no imports, no
//     network, no data collection — read every line), prints the shaved
//     text on the original streams, and exits with the child's exit code.
//
// No rule matches a command → no rewrite → the original runs untouched.
// Sandboxed commands are never rewritten: the wrapper would run them
// unsandboxed, and that is a behavior change we refuse to make.

${engine}

const TSH_WRAP_TAG = "tsh-cursor-wrap";

/** conservative whitelist: engine rules with a name, or npm-style test invocations */
function tshShouldWrap(cmd) {
  const rule = ruleFor(cmd);
  if (rule.name !== "generic") return true;
  // ruleFor's named rules cover "vitest ...", "npm install ...", "tsc ..."
  // but plain "npm test" / "npm run test" fall through to generic
  if (/^(npm|pnpm|yarn|bun)\\s+(run\\s+)?(test|ci)\\b/.test(cmd)) return true;
  if (/^npm\\s+run\\s+(test|build|lint|check)\\b/.test(cmd)) return true;
  return false;
}

function tshDecision(input) {
  try {
    const e = JSON.parse(input);
    if (!e || e.hook_event_name !== "preToolUse") return null;
    if (e.tool_name !== "Shell") return null;
    const ti = e.tool_input;
    if (!ti || typeof ti !== "object" || typeof ti.command !== "string" || ti.command.trim() === "") return null;
    // sandboxed commands must keep their sandbox — never rewrite those
    if (e.sandbox === true || ti.sandbox === true) return null;
    if (ti.command.includes(TSH_WRAP_TAG)) return null; // already wrapped
    if (!tshShouldWrap(ti.command)) return null;
    const self = process.argv[1] ?? "";
    if (!self) return null; // no self path to point the rewrite at: pass through
    const b64 = Buffer.from(ti.command, "utf8").toString("base64");
    return JSON.stringify({
      permission: "allow",
      updated_input: {
        ...(typeof ti === "object" ? ti : {}),
        command: "node " + JSON.stringify(self) + " " + b64 + " " + TSH_WRAP_TAG,
      },
    });
  } catch {
    return null;
  }
}

// --- wrapper mode -------------------------------------------------------------

const TSH_CAPTURE_CAP = 2 * 1024 * 1024; // chars kept per stream (head+tail when exceeded)

function tshCap(text) {
  const n = text.length;
  if (n <= TSH_CAPTURE_CAP * 2) return text;
  return (
    text.slice(0, TSH_CAPTURE_CAP) +
    "\\n\\u2425 (tokenshave: capture capped — dropped " +
    (n - TSH_CAPTURE_CAP * 2) +
    " chars in the middle)\\n" +
    text.slice(n - TSH_CAPTURE_CAP)
  );
}

function tshShave(cmdName, text) {
  try {
    const r = shave(cmdName, text);
    // the engine hands back byte-identical text when nothing was shaved;
    // keep the shave only when it is strictly smaller (never bigger)
    return r.output.length < text.length ? r.output : text;
  } catch {
    return text; // engine failure → raw output, token-identical behavior
  }
}

function tshRunWrapper(cp, b64) {
  let cmd;
  try {
    cmd = Buffer.from(b64, "base64").toString("utf8");
  } catch {
    process.exit(1); // un-decodable arg: go loud (exit 1 ≠ 2 — hook-side fail-open)
  }
  const child = cp.spawn(cmd, {
    shell: true,
    stdio: ["inherit", "pipe", "pipe"],
    cwd: process.cwd(),
  });

  let out = "";
  let err = "";
  child.stdout.on("data", (c) => { out += c; });
  child.stderr.on("data", (c) => { err += c; });

  // keep the wrapper from outliving the terminal's kill signal
  for (const sig of ["SIGINT", "SIGTERM", "SIGBREAK"]) {
    try {
      process.on(sig, () => { try { child.kill(sig); } catch {} });
    } catch {}
  }

  child.on("close", (code) => {
    try {
      if (out) process.stdout.write(tshShave(cmd, tshCap(out)));
      if (err) process.stderr.write(tshShave(cmd, tshCap(err)));
    } catch {
      // last resort: print what we have, raw
      try { if (out) process.stdout.write(out); } catch {}
      try { if (err) process.stderr.write(err); } catch {}
    }
    // preserve the child's exit code semantics; a signal-killed child has
    // exitCode null — report 1 (≠ 2, which would mean hook-side denial)
    process.exit(typeof code === "number" ? code : 1);
  });
  child.on("error", () => process.exit(1));
}

if (process.argv[3] === TSH_WRAP_TAG) {
  // wrapper mode: the base64 payload is argv[2]; child_process loads via
  // dynamic import, which works whether this file is treated as CJS or ESM
  import("node:child_process").then(
    (cp) => tshRunWrapper(cp, process.argv[2]),
    () => process.exit(1),
  );
} else {
  // hook mode
  const tshChunks = [];
  process.stdin.on("data", (c) => tshChunks.push(c));
  process.stdin.on("end", () => {
    let decision = null;
    try {
      decision = tshDecision(Buffer.concat(tshChunks).toString("utf8"));
    } catch {
      decision = null;
    }
    // valid allow on every path — never empty, never a deny, never exit 2
    process.stdout.write(decision ?? JSON.stringify({ permission: "allow" }));
    process.exit(0);
  });
}
`;
    return { hooksJson, wrapJs };
}
